import static org.junit.Assert.assertNull;

/**
 * Unit tests for SourceFile.getLine.
 */
public class SourceFile_getLine_TriageGen1Test {



    @Test
    public void testGetLine_CachingMechanism() {
        String code = "line1\nline2\nline3\nline4";
        SourceFile sourceFile = SourceFile.fromCode("test.js", code);

        // Test jumping forward (triggers lastOffset/lastLine logic)
        assertEquals("line1", sourceFile.getLine(1));
        assertEquals("line3", sourceFile.getLine(3));

        // Test requesting a line that is the same as lastLine (pos stays at lastOffset)
        assertEquals("line3", sourceFile.getLine(3));

        // Test requesting a line that is greater than lastLine
        assertEquals("line4", sourceFile.getLine(4));
    }












}

