public class SourceFile_getLine_TriageGen1Test {









    @Test
    public void testGetLine_TrailingNewline() {
        // If the file ends with a newline, the last line might be empty or null depending on logic
        String code = "line1\nline2\n";
        SourceFile sourceFile = SourceFile.fromCode("test.js", code);

        assertEquals("line1", sourceFile.getLine(1));
        assertEquals("line2", sourceFile.getLine(2));
